            if re.search(r'[\\/]obj[\\/]',c.get('filename')): continue
            for l in c.iter('line'):
                k=(p.get('name'),c.get('filename'),l.get('number'));h=int(l.get('hits'))
                L[k]=max(L.get(k,0),h)
def pct(ks): return 100*sum(1 for k in ks if L[k]>0)/len(ks) if ks else 0
print('Core %.2f'%pct([k for k in L if k[0]=='TutorFlow.Core']))
print('Total %.2f'%pct(list(L)))
EOF
