const fs=require('fs');const path=require('path');
function walk(d){return fs.readdirSync(d,{withFileTypes:true}).flatMap(e=>e.isDirectory()?walk(path.join(d,e.name)):[path.join(d,e.name)])}
const prod=['TutorFlow.Core','TutorFlow.Infrastructure','TutorFlow.Api'];const L=new Map();
for(const f of walk(process.argv[2]).filter(x=>x.endsWith('.cobertura.xml'))){
 const x=fs.readFileSync(f,'utf8');
 for(const pm of x.matchAll(/<package name="([^"]+)"[\s\S]*?<\/package>/g)){
  if(!prod.includes(pm[1]))continue;
  for(const cm of pm[0].matchAll(/<class [^>]*filename="([^"]+)"[\s\S]*?<\/class>/g)){
   if(/[\\\/]obj[\\\/]/.test(cm[1]))continue;
   for(const lm of cm[0].matchAll(/<line number="(\d+)" hits="(\d+)"/g)){
    const k=pm[1]+'|'+cm[1]+'|'+lm[1];L.set(k,Math.max(L.get(k)||0,+lm[2]))}}}}
const pct=ks=>ks.length?100*ks.filter(k=>L.get(k)>0).length/ks.length:0;
const keys=[...L.keys()];
console.log('Core',pct(keys.filter(k=>k.startsWith('TutorFlow.Core|'))).toFixed(2));
console.log('Total',pct(keys).toFixed(2));
EOF
node ../cov.js .

